SELECT (SELECT h.decision FROM trade_signal h WHERE h.symbol=w.symbol AND h.interval_code='1h' AND h.generated_at<=w.opened_at ORDER BY h.generated_at DESC LIMIT 1) AS entry_1h_raw, COUNT(*) AS n, SUM(p.realized_pnl<0) AS losers, ROUND(SUM(p.realized_pnl),6) AS pnl_sum FROM wallet_managed_position w JOIN paper_position p ON p.symbol=w.symbol AND ABS(TIMESTAMPDIFF(SECOND,p.opened_at,w.opened_at))<=5 WHERE w.opened_at >= '2026-10-03 00:00:00' AND p.closed_at IS NOT NULL GROUP BY entry_1h_raw ORDER BY entry_1h_raw LIMIT 20;